import React from 'react';

import { Dropdown, DropdownMenu, DropdownProps } from 'react-bootstrap';

import styles from './styles.module.less';

interface IPohDropdownProps extends DropdownProps {
  id?: string;
  menu: React.ReactNode;
  open?: boolean;
  children: React.ReactElement<any> | React.ReactElement<any>[];
}

const PohDropdown: React.FC<IPohDropdownProps> = ({
  id,
  children,
  menu,
  open = false,
  ...anotherProps
}) => {
  return (
    <Dropdown {...anotherProps}>
      {children && (
        <Dropdown.Toggle as="span" split={false} className={styles.dd}>
          {children}
        </Dropdown.Toggle>
      )}

      <DropdownMenu show={open}>{menu}</DropdownMenu>
    </Dropdown>
  );
};

export default PohDropdown;
